async def act(page):
    """
    Navigate to the Magento Admin Coupons report, set the date range from
    05/01/2021 to 05/15/2023, show the report, and attempt to export a CSV.

    Notes on KB helpers:
    - There are several dashboard-centric KB helpers (generate_sales_summary_for_date_range,
      export_dashboard_snapshot, export_orders_csv, download_revenue_and_orders_report,
      export_revenue_and_orders, export_customers_csv_via_grid). All of them operate
      against the Admin Dashboard or specific grids (Customers/Orders) and none
      specifically implement the Coupons report workflow. Therefore none are used.
    """
    import re

    # Navigate to the Coupons report (relative path per guidance)
    await page.goto('/index.php/admin/report/sales/coupons/')
    await page.wait_for_load_state('networkidle')

    # Do NOT change language settings. We will not touch the language combobox.

    # Helper: try to fill a date field using common accessible patterns
    async def fill_date(field_labels, value):
        # Try get_by_label first
        for label in field_labels:
            try:
                locator = page.get_by_label(label)
                if await locator.count():
                    await locator.fill(value)
                    return True
            except Exception:
                pass
        # Try role=textbox with name match
        try:
            tbs = page.get_by_role('textbox')
            tb_count = await tbs.count()
            for i in range(tb_count):
                tb = tbs.nth(i)
                try:
                    name = ''
                    # accessible name via get_attribute aria-label/name
                    try:
                        name = (await tb.get_attribute('aria-label')) or ''
                    except Exception:
                        name = ''
                    # fallback to inner text of associated label or placeholder
                    if not name:
                        try:
                            name = (await tb.get_attribute('placeholder')) or ''
                        except Exception:
                            name = ''
                    if any(p.lower() in (name or '').lower() for p in field_labels):
                        await tb.fill(value)
                        return True
                except Exception:
                    pass
        except Exception:
            pass
        return False

    # Common label candidates for From/To fields in Magento admin reports
    from_candidates = ['From', 'From Date', 'Start', 'Start Date', 'Date From']
    to_candidates = ['To', 'To Date', 'End', 'End Date', 'Date To']

    # Fill the dates desired by the task
    await fill_date(from_candidates, '05/01/2021')
    await fill_date(to_candidates, '05/15/2023')

    # Click the Show Report button (try direct name match, else search heuristically)
    show_clicked = False
    try:
        show_btn = page.get_by_role('button', name=re.compile(r"show\s*report", re.I))
        if await show_btn.count():
            # If the button may be in a group, get the first instance (scoped clicks are recommended,
            # but we don't have a stable parent role in the generic tree). Click the found button.
            await show_btn.first.click()
            show_clicked = True
    except Exception:
        pass

    if not show_clicked:
        # Heuristic: find any button containing 'show' and 'report' in its visible text
        try:
            btns = page.get_by_role('button')
            n = await btns.count()
            for i in range(n):
                b = btns.nth(i)
                try:
                    txt = (await b.inner_text() or '').strip()
                    if txt and 'show' in txt.lower() and 'report' in txt.lower():
                        await b.click()
                        show_clicked = True
                        break
                except Exception:
                    pass
        except Exception:
            pass

    # Allow the report to render/refresh after clicking Show Report
    if show_clicked:
        await page.wait_for_timeout(1500)

    # Attempt to export CSV. Strategy:
    # 1) Look for a combobox with an option that contains 'CSV' and select it, then click an Export button.
    # 2) If that fails, click a literal 'Export' button and capture download.
    # 3) If there is a 'CSV' link, click it and capture.

    # 1) Combobox-based export
    try:
        comboboxes = page.get_by_role('combobox')
        cb_count = await comboboxes.count()
        for i in range(cb_count):
            cb = comboboxes.nth(i)
            try:
                # get_by_role('option') on the combobox
                opts = cb.get_by_role('option')
                # read option visible texts defensively
                opt_texts = []
                opt_count = await opts.count()
                for j in range(opt_count):
                    try:
                        opt_texts.append((await opts.nth(j).inner_text()) or '')
                    except Exception:
                        opt_texts.append('')
                for text in opt_texts:
                    if text and 'csv' in text.lower():
                        # select by exact label text as read from DOM
                        try:
                            await cb.select_option(label=text)
                        except Exception:
                            # narrow fallback: try selecting by visible text trimmed
                            try:
                                await cb.select_option(label=text.strip())
                            except Exception:
                                pass
                        # After selecting CSV, try to click Export button
                        try:
                            export_btn = page.get_by_role('button', name=re.compile('export', re.I))
                            if await export_btn.count():
                                with page.expect_download() as dd:
                                    await export_btn.first.click()
                                download = await dd.value
                                filename = 'coupons_report.csv'
                                await download.save_as(filename)
                                print(filename)
                                return
                        except Exception:
                            pass
            except Exception:
                pass
    except Exception:
        pass

    # 2) Direct Export button
    try:
        export_btn = page.get_by_role('button', name=re.compile('export', re.I))
        if await export_btn.count():
            try:
                with page.expect_download() as dd:
                    await export_btn.first.click()
                download = await dd.value
                filename = 'coupons_report.csv'
                await download.save_as(filename)
                print(filename)
                return
            except Exception:
                # no immediate download - continue to next strategy
                pass
    except Exception:
        pass

    # 3) CSV link
    try:
        csv_link = page.get_by_role('link', name=re.compile('csv', re.I))
        if await csv_link.count():
            try:
                with page.expect_download() as dd:
                    await csv_link.first.click()
                download = await dd.value
                filename = 'coupons_report.csv'
                await download.save_as(filename)
                print(filename)
                return
            except Exception:
                pass
    except Exception:
        pass

    # If we couldn't produce a download, print the report region's text so caller can inspect it
    try:
        # Prefer a role='region' or role='document' that likely contains the report
        doc = page.get_by_role('document')
        if await doc.count():
            txt = await doc.first.inner_text()
            print(txt)
            return
    except Exception:
        pass

    try:
        region = page.get_by_role('region')
        if await region.count():
            txt = await region.first.inner_text()
            print(txt)
            return
    except Exception:
        pass

    # Final fallback: print empty string for deterministic output
    print('')

